def find_golomb(n=10, max_length=100):
    def backtrack(pos, used_diffs):
        if len(pos) == n:
            return pos
        start = pos[-1] + 1
        for next_pos in range(start, max_length + 1):
            diffs = [next_pos - p for p in pos]
            if any(d in used_diffs for d in diffs):
                continue
            new_diffs = used_diffs | set(diffs)
            result = backtrack(pos + [next_pos], new_diffs)
            if result:
                return result
        return None
    return backtrack([0], set())

